window.DOSIK=window.DOSIK||{};DOSIK["kb_otsu4_phys"]={"1":[{"t":"table","title":"状態変化","head":["変化","意味"],"rows":[["凝固","液体が固体になることである。"],["昇華","固体が気体になることである。"],["蒸発","液体が気体になることである。"],["沸騰","液体内部から気泡が出て、激しく蒸発することをいう。"]]},{"t":"cause","title":"沸騰","causes":["外圧と液体の飽和蒸気圧が等しくなれば沸騰する。","液体の温度が高いほど、飽和蒸気圧は高くなる。"],"result":"気圧が高くなると、沸点も上昇する。","effects":["沸点が低い液体ほど蒸発しやすい。"]},{"t":"def","term":"物質の3つの状態","text":"物質には、固体、液体、気体の3つの状態がある。","ex":["水の密度は、約4℃において最大となる。"]}],"2":[{"t":"def","term":"比熱","text":"単位質量の物体の温度を1℃だけ高めるのに要する熱量を、その物体の比熱という。","ex":["1気圧において1gの水を温度1K（1℃）高めるのに要する熱量は、4.186Jである。"]},{"t":"vs","title":"比熱の大小","cols":[{"name":"比熱が大きい","items":["比熱の大きい物質は温まりにくく冷めにくい。"]},{"name":"比熱が小さい","items":["比熱が小さい物質ほど熱しやすく冷めやすい。"]}]},{"t":"tree","title":"熱の移動","root":"熱の移動","branches":[["伝導","温度の異なる2つの物質を接触させると、温度の高い方から低い方へ移る。 · 金属は、非金属よりも熱伝導率が大きい。 · 固体、液体、気体のうち、熱伝導率は固体が最も大きい。"],["対流","ガスこんろで水を沸かすと、水が表面から温かくなるのは熱の対流によるものである。"],["放射（ふく射）","放射熱は、物質にあたると吸収、反射、透過する。"]]},{"t":"def","term":"沸騰中の水温","text":"水が沸騰を開始してから蒸気になるまでは、水の温度は一定である。"}],"3":[{"t":"cause","title":"静電気の発生","causes":["電気の不導体の摩擦等によって発生する。","電気の不導体は帯電しやすい。","一般に合成繊維製品は、綿製品より帯電しやすい。","湿度が低いほうが帯電しやすい。"],"result":"静電気の蓄積","effects":["静電気が蓄積すると、火花放電を発生することがある。","静電気は、湿度が低いと蓄積しやすい。"]},{"t":"tree","title":"静電気の防止","root":"静電気の防止","branches":[["接地","帯電防止策として、接地する方法がある。 · 静電気の蓄積を防止する方法として、接地がある。"],["湿度","湿度を上げて静電気の防止に努めた。"],["流速","液体の危険物は流速を下げて静電気の防止に努めた。"],["衣服","従業員の衣服を化学繊維から綿素材へと変更した。"],["除電","除電器を使用してこまめに除電し静電気の防止に努めた。"]]}],"5":[{"t":"vs","title":"酸化剤と還元剤","cols":[{"name":"酸化剤","items":["他の物質から水素を奪う性質のあるもの","他の物質から還元されやすい性質のあるもの","電子を受け取りやすく還元されやすい。"]},{"name":"還元剤","items":["他の物質に水素を与える性質のあるもの","他の物質から酸化されやすい性質のあるもの","ナトリウムやカリウムは、還元剤としての性質をもつ。"]}]},{"t":"def","term":"酸化還元の相手","text":"反応する相手の物質によって、酸化剤として作用したり、還元剤として作用したりする物質がある。","ex":["加硫ゴムが劣化する主な原因の一つに、酸化反応がある。"]},{"t":"def","term":"気体の体積","text":"気体体積は温度1℃上昇するごとに0℃のときの体積の1/273ずつ増加する。"}],"6":[{"t":"vs","title":"酸と塩基","cols":[{"name":"酸","items":["水に溶けて水素イオンH +を生じる物質、または他の物質に水素イオンH +を与えることができる物質をいう。"]},{"name":"塩基","items":["水に溶けて水酸化物イオンOH -を生じる物質、または他の物質から水素イオンH +を受け取ることができる物質をいう。"]}]},{"t":"def","term":"中和","text":"酸と塩基が反応し互いにその性質を打ち消しあうことをいう。","ex":["酸性・塩基性の強弱は、水素イオン指数（pH）で表される。"]},{"t":"tree","title":"加水分解する物質","root":"加水分解する","branches":[["弱酸と弱塩基","弱酸と弱塩基からできた塩は、加水分解する。"],["強酸と弱塩基","強酸と弱塩基からできた塩は、加水分解する。"],["弱酸と強塩基","弱酸と強塩基からできた塩は、加水分解する。"],["エステル","カルボン酸とアルコールからできたエステルは、加水分解する。"]]}],"7":[{"t":"table","title":"物質の種類","head":["種類","意味・例"],"rows":[["化合物","2種類以上の元素が化合によってできるものである。 · 食塩は、ナトリウムと塩素の化合物である。 · エタノールは、水素、炭素と酸素の化合物である。"],["単体","1つの元素のみで構成される物質である。"],["混合物","空気は、窒素、酸素その他の混合物である。 · 灯油は、種々の炭化水素の混合物である。"]]},{"t":"vs","title":"中和と酸化","cols":[{"name":"中和","items":["酸と塩基が反応して水と塩ができる化学反応である。"]},{"name":"酸化","items":["物質が酸素と化合することである。"]}]},{"t":"tree","title":"物質の性質","root":"性質の例","branches":[["ナトリウム","炎色反応で黄色を示す。"],["液体酸素","淡青色である。"],["希ガス元素","反応しない。 · 常温（20℃）では、いくら加圧しても液体にならない。"]]}],"8":[{"t":"def","term":"燃焼","text":"物質が酸素と化合して安定な酸化物に変化する反応のうち、熱と光の発生を伴うものを燃焼という。","ex":["燃焼は、急激な発熱、発光等を伴う酸化反応である。","可燃物は、燃焼により安定な酸化物に変化する。"]},{"t":"tree","title":"燃焼の3要素","root":"燃焼の3要素とは、可燃物、酸素供給源及び点火源のことである。","branches":[["可燃物","固体の可燃物は、細かく砕くと燃焼しやすくなる。 · 高引火点の可燃性液体でも、綿糸に染み込ませると容易に着火する。"],["酸素供給源","反応物質としての可燃物と酸素供給源が必要である。"],["点火源","可燃物と酸素の反応を起こすために必要なエネルギーを与えるものである。 · 反応を開始させるための着火エネルギーが必要である。"]]},{"t":"cause","title":"粉じん爆発","causes":["可燃性固体の微粉が空中に浮遊しているときに、何らかの火源により爆発する現象をいう。","粉じんが空気とよく混合している浮遊状態が必要である。"],"result":"粉じん爆発","effects":["粉じんが大きい粒子の場合は、簡単に浮遊しないので爆発の危険性は低い。","開放空間では爆発の危険性は低い。"]}],"9":[{"t":"def","term":"燃焼範囲","text":"燃焼可能な混合気体の可燃性ガスの濃度範囲をいう。","ex":["可燃性ガスの種類により異なる。","同じ可燃性ガスでも、温度が高くなると、燃焼下限界の値は小さくなる。","同じ可燃性ガスでも、圧力が低くなると、燃焼範囲は狭くなる。"]},{"t":"def","term":"燃焼点","text":"燃焼を継続させるのに必要な可燃性蒸気が供給される温度をいう。"},{"t":"table","title":"引火と発火","head":["項目","内容"],"rows":[["蒸気","蒸気は、空気の2.7倍の重さである。"],["引火","液温が－11℃のとき、液面近くの空気中に1.4vol%の濃度の蒸気が発生する。"],["沸騰","80℃に加熱すると沸騰する。"],["発火","500℃以上に加熱すると、火炎などを近づけなくても発火する。"]]}],"11":[{"t":"tree","title":"水による消火","root":"水による消火が有効なのは","branches":[["蒸発熱","水の持つ蒸発熱の大きさによる冷却効果である。"],["比熱","水の持つ比熱の大きさによる冷却効果である。"],["窒息","発生する水蒸気による窒息効果である。"],["希釈","発生する水蒸気が可燃性ガスを希釈するからである。"]]},{"t":"table","title":"消火剤","head":["消火剤","効果"],"rows":[["粉末消火剤","燃焼を化学的に抑制する効果と窒息効果がある。"],["二酸化炭素消火剤","空気中の酸素濃度を低下させて、窒息効果により消火する。"],["窒素消火剤","空気中の酸素濃度を低下させて窒息効果により消火をする。"],["泡消火器","泡で燃焼を覆うので窒息効果があり、油火災に適する。"]]},{"t":"table","title":"消火の方法","head":["方法","内容"],"rows":[["除去","可燃物を取り去るために、配管の元弁を閉鎖してガスや油の供給を停止する。"],["冷却","燃焼物を引火点または分解温度未満の温度に冷却するために、水または水系の消火剤を放射する。"],["窒息","酸素の供給を遮断するために、泡消火剤で可燃物を覆う。 · 空気中の酸素が一定濃度以下になり不足すると、燃焼は停止する。"]]}],"12":[{"t":"table","title":"危険物の物理的性質","head":["項目","内容"],"rows":[["体膨張","収納されている危険物が体膨張して容器が破損するのを防ぐため。"],["凝固点","食塩水は、純水よりも凝固点（融点）が低い。"],["比重","比重が同じであれば、同一体積の物体の質量は同じである。"]]}]};
